import{_ as a,o as t,a as l,b as d}from"./app.C41L12d5.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"附录","link":"/guide/programming_guide/appendix/show_kernel_debug_data_tool"},{"text":"show_kernel_debug_data工具","link":"/guide/programming_guide/appendix/show_kernel_debug_data_tool"}]},"headers":[],"relativePath":"guide/programming_guide/appendix/show_kernel_debug_data_tool.md","filePath":"guide/programming_guide/appendix/show_kernel_debug_data_tool.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"工具安装","slug":"工具安装","link":"#工具安装"},{"level":2,"title":"使用方法","slug":"使用方法","link":"#使用方法"},{"level":2,"title":"产物说明","slug":"产物说明","link":"#产物说明"}],"lastUpdated":1788309328000}'),i={name:"guide/programming_guide/appendix/show_kernel_debug_data_tool.md"};function s(n,e,o,h,c,p){return t(),l("div",null,[...e[0]||(e[0]=[d(`<div><article class="markdown-body"><h1>show_kernel_debug_data工具</h1><p>在Ascend C算子程序代码中，用户可以使用AscendC::<a href="../../../api/SIMD-API/basic_api/debug_interface/onboard_print/DumpTensor.html">DumpTensor</a>、AscendC::<a href="../../../api/Utils-API/tuning_interface/printf.html">printf</a>、AscendC::<a href="../../../api/SIMD-API/basic_api/debug_interface/onboard_print/PrintTimeStamp.html">PrintTimeStamp</a>、<a href="../../../api/Utils-API/tuning_interface/assert.html">ascendc_assert</a>接口打印相关调试信息，并通过aclInit接口或直接配置acl.json文件，启用Dump配置，导出Ascend C算子核函数（Kernel）的调测信息。本工具提供了对调测信息的离线解析能力，帮助用户获取并解析调试信息，即将导出的bin文件解析成可读格式。本工具的使用示例可参考<a href="https://gitcode.com/cann/asc-tools/tree/master/examples/01_show_kernel_debug_data">show_kernel_debug_data样例</a>。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>show_kernel_debug_data支持多用户并发调用，但用户需要指定不同的落盘路径，否则可能出现落盘内容被覆盖等问题。</p></div><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品：支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="工具安装">工具安装<a class="header-anchor" href="#工具安装">​</a></h2><ol><li><p>安装工具。</p><p>工具跟随CANN软件包发布（参考<a href="../../getting_started/environment_setup.html">环境准备</a>完成CANN安装），其路径默认为<code>\${INSTALL_DIR}/tools/show\\_kernel\\_debug\\_data</code>，其中<code>\${INSTALL_DIR}</code>请替换为CANN软件安装后文件存储路径。以root用户安装为例，安装后文件默认存储路径为：/usr/local/Ascend/cann。</p></li><li><p>设置环境变量。</p><ul><li><p>root用户安装Ascend-cann-toolkit包时</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>source /usr/local/Ascend/cann/set_env.sh
</code></pre></div></li><li><p>非root用户安装Ascend-cann-toolkit包时</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>source \${HOME}/Ascend/cann/set_env.sh
</code></pre></div></li></ul></li><li><p>检查工具是否安装成功。</p><p>执行如下命令，若能正常显示--help或-h信息，则表示工具环境正常，功能可正常使用。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>show_kernel_debug_data -h
</code></pre></div></li></ol><h2 id="使用方法">使用方法<a class="header-anchor" href="#使用方法">​</a></h2><ul><li><p><strong>命令行方式</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>show_kernel_debug_data &lt;bin_file_path&gt; [&lt;output_path&gt;]
</code></pre></div><table><thead><tr><th>参数</th><th>可选/必选</th><th>说明</th></tr></thead><tbody><tr><td>&lt;bin_file_path&gt;</td><td>必选</td><td>kernel侧调试信息落盘的bin文件或包含bin文件的目录路径，例如“/input/dump_workspace.bin”。</td></tr><tr><td>&lt;output_path&gt;</td><td>可选</td><td>解析结果的保存路径，例如“/output_dir”。默认是当前命令行执行目录下。</td></tr></tbody></table></li><li><p><strong>API方式</strong></p><p>获取kernel侧调试信息并解析成可读文件。函数原型如下。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>def show_kernel_debug_data(bin_file_path: str, output_path: str = &#39;./&#39;) -&gt; None
</code></pre></div><p>其中，输入参数说明如下。函数无输出参数和返回值。</p><ul><li>bin_file_path：kernel侧调试信息落盘的bin文件或包含bin文件的目录路径，字符串类型。</li><li>output_path：解析结果的保存路径，字符串类型，默认是当前接口调用脚本所在目录下。</li></ul><p>调用示例参考如下代码。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>from show_kernel_debug_data import show_kernel_debug_data
show_kernel_debug_data(./input/dump_workspace.bin)
</code></pre></div></li></ul><h2 id="产物说明">产物说明<a class="header-anchor" href="#产物说明">​</a></h2><p>工具解析结果文件目录结构如下。其中，dump_data目录是对DumpTensor、PrintTimeStamp接口解析的结果，index0对应DumpTensor接口中第二个参数desc=0时的打印，loop0表示切分后首个分块的数据打印。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>├ \${output_path}
├── PARSER_\${timestamp}                     // \${timestamp}表示时间戳
     ├── dump_data
     │   ├── 0                             // core0解析结果
     │   ├── core_0_index_0_loop_0.bin     // core0 desc0 progress0落盘信息
     │   ├── core_0_index_0_loop_0.txt     // core0 desc0 progress0解析结果
      ...
     │   ├── core_0_index_2_loop_15.bin    // core0 desc2 progress15落盘信息
     │   ├── core_0_index_2_loop_15.txt    // core0 desc2 progress15解析结果
     │   └── time_stamp_core_0.csv         // 时间戳信息
     │   ├── 1                             // core1解析结果
     │   ├── 2                             // core2解析结果
      ...
     │   └── index_dtype.json              // index与数据类型的映射关系
     └── parser.log                         // 解析日志，包括printf、ascendc_assert接口的打印信息
</code></pre></div></article></div>`,1)])])}const v=a(i,[["render",s]]);export{_ as __pageData,v as default};
